&lt;%
// Edit this list to control which categories appear and in what order.
// A project tagged with more than one category will show up under each
// of its matching categories. Any project whose categories don't match
// anything below will be grouped under "Other".
const categoryOrder = [
  "Research",
  "Water Security",
  "Environmental Engineering",
  "Data-viz",
  "Design",
  "Built Environment",
  "Writing"
];

const groups = new Map();
categoryOrder.forEach((cat) =&gt; groups.set(cat, []));

const other = [];
for (const item of items) {
  const cats = item.categories || [];
  let matched = false;
  for (const cat of categoryOrder) {
    if (cats.includes(cat)) {
      groups.get(cat).push(item);
      matched = true;
    }
  }
  if (!matched) other.push(item);
}
if (other.length) groups.set("Other", other);

const visibleCategories = [...groups.keys()].filter((cat) =&gt; groups.get(cat).length &gt; 0);
%&gt;


  Filter by category

    All
    &lt;% for (const category of visibleCategories) { %&gt;
      &lt;%= category %&gt;
    &lt;% } %&gt;





&lt;% for (const [category, catItems] of groups) { %&gt;
&lt;% if (catItems.length &gt; 0) { %&gt;



    &lt;%= category %&gt;



    &lt;% for (const item of catItems) { %&gt;

      &gt;


          &lt;%= item.title %&gt;
          &lt;%= item.description %&gt;



    &lt;% } %&gt;





&lt;% } %&gt;
&lt;% } %&gt;
